CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','blocked')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid REFERENCES users(id),admin_version text,role text NOT NULL CHECK(role IN ('user','admin')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS plans(id text PRIMARY KEY,name text NOT NULL,price_cents integer NOT NULL CHECK(price_cents>0),interval_months integer NOT NULL CHECK(interval_months IN (1,12)),max_devices integer NOT NULL CHECK(max_devices BETWEEN 1 AND 20),ai_quota integer NOT NULL DEFAULT 0,credits integer NOT NULL CHECK(credits>0),features jsonb NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subscriptions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),plan_id text NOT NULL REFERENCES plans(id),provider_id text UNIQUE,checkout_url text,status text NOT NULL,amount_cents integer NOT NULL,credits integer NOT NULL,interval_months integer NOT NULL,currency text NOT NULL DEFAULT 'BRL',paid_until timestamptz,cancel_at_period_end boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_subscription ON subscriptions(user_id) WHERE status IN ('creating','pending','authorized','active');
CREATE TABLE IF NOT EXISTS payments(provider_id text PRIMARY KEY,invoice_id text UNIQUE NOT NULL,subscription_id uuid NOT NULL REFERENCES subscriptions(id),status text NOT NULL,amount_cents integer NOT NULL,currency text NOT NULL,period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,paid_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS licenses(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),plan_id text NOT NULL REFERENCES plans(id),key_hash text UNIQUE NOT NULL,key_prefix text NOT NULL,source text NOT NULL CHECK(source IN ('subscription','manual')),expires_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_subscription_key ON licenses(user_id) WHERE source='subscription' AND revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY,license_id uuid NOT NULL REFERENCES licenses(id),fingerprint text NOT NULL,name text NOT NULL,platform text NOT NULL,token_hash text UNIQUE NOT NULL,revoked_at timestamptz,last_seen timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(license_id,fingerprint));
CREATE TABLE IF NOT EXISTS webhook_events(id bigserial PRIMARY KEY,event_key text UNIQUE NOT NULL,topic text NOT NULL,resource_id text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_credentials(provider text PRIMARY KEY CHECK(provider IN ('anthropic','openai')),encrypted_value text NOT NULL,last_four text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage(user_key text NOT NULL,month text NOT NULL,analyses integer NOT NULL DEFAULT 0,PRIMARY KEY(user_key,month));
CREATE TABLE IF NOT EXISTS ai_requests(id uuid PRIMARY KEY,device_id uuid NOT NULL REFERENCES devices(id),wallet_key text NOT NULL,reserved bigint NOT NULL,charged bigint,status text NOT NULL,result jsonb,usage jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,actor text NOT NULL,event text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS webhook_pending ON webhook_events(status,available_at);
CREATE INDEX IF NOT EXISTS subscriptions_user ON subscriptions(user_id);
CREATE TABLE IF NOT EXISTS rate_limits(key text NOT NULL,bucket bigint NOT NULL,count integer NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '2 days',PRIMARY KEY(key,bucket));
CREATE TABLE credit_packages(id text PRIMARY KEY,name text NOT NULL,credits integer NOT NULL CHECK(credits>0),price_cents integer NOT NULL CHECK(price_cents>0),active boolean NOT NULL DEFAULT true);
CREATE TABLE credit_orders(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),package_id text NOT NULL REFERENCES credit_packages(id),credits integer NOT NULL,amount_cents integer NOT NULL,provider_id text UNIQUE,payment_id text UNIQUE,checkout_url text,status text NOT NULL DEFAULT 'creating',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets(key text PRIMARY KEY,balance bigint NOT NULL DEFAULT 0);
CREATE TABLE credit_grants(source text PRIMARY KEY,wallet_key text NOT NULL REFERENCES wallets(key),amount bigint NOT NULL,active boolean NOT NULL);
CREATE TABLE credit_ledger(id bigserial PRIMARY KEY,wallet_key text NOT NULL REFERENCES wallets(key),delta bigint NOT NULL,reason text NOT NULL,reference text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX credit_ledger_wallet ON credit_ledger(wallet_key,created_at DESC);
CREATE TABLE commercial_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),fx numeric NOT NULL DEFAULT 6.5 CHECK(fx>0),fee_pct numeric NOT NULL DEFAULT 6 CHECK(fee_pct BETWEEN 0 AND 100),reserve_pct numeric NOT NULL DEFAULT 10 CHECK(reserve_pct BETWEEN 0 AND 100),min_margin_pct numeric NOT NULL DEFAULT 55 CHECK(min_margin_pct BETWEEN 0 AND 90));
